/// <summary>
/// Check whether the version exists.
/// </summary>
/// <param name = "_eInvoiceVersionId">Unique eInvoice version Id</param>
/// <returns>A boolean value, true if the vesion Id is found else false.</returns>
public static boolean exist(METeInvoiceVersionId _eInvoiceVersionId)
{
    boolean isFound;

    isFound = _eInvoiceVersionId
                && (select firstonly RecId from METeInvoiceVersionsTable
                        where METeInvoiceVersionsTable.VersionId == _eInvoiceVersionId).RecId != 0;

    return isFound;
}

/// <summary>
/// Finds the specified record in the <c>METeInvoiceVersionsTable</c> table.
/// </summary>
/// <param name = "_eInvoiceVersionId">Unique eInvoice version Id</param>
/// <param name = "_forUpdate">Determine if record found is to be updated, defaulting values is false.</param>
/// <returns>A unique record of the <c>METeInvoiceVersionsTable</c> table.</returns>
static METeInvoiceVersionsTable find(METeInvoiceVersionId _eInvoiceVersionId, boolean _forUpdate = false)
{
    METeInvoiceVersionsTable eInvoiceVersionsTable;

    if (_eInvoiceVersionId)
    {
        if (_forUpdate)
        {
            eInvoiceVersionsTable.selectForUpdate(_forUpdate);
        }

        select firstonly eInvoiceVersionsTable
            where eInvoiceVersionsTable.VersionId == _eInvoiceVersionId;
    }

    return eInvoiceVersionsTable;
}

/// <summary>
/// Displays a lookup selection for the <c>METeInvoiceVersionsTable</c> table.
/// </summary>
/// <param name = "_formStringControl">The control for which lookup is performed.</param>
public static void lookupEInvoiceVersions(FormStringControl _formStringControl)
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(METeInvoiceVersionsTable), _formStringControl);

    Query query = new Query();

    query.addDataSource(tablenum(METeInvoiceVersionsTable));
    sysTableLookup.addLookupfield(fieldnum(METeInvoiceVersionsTable, VersionId));
    sysTableLookup.addLookupfield(fieldnum(METeInvoiceVersionsTable, Description));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
